import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"21、【噬嗑】 震下離上","description":"周易尚氏學 - 21、【噬嗑】 震下離上","frontmatter":{"title":"21、【噬嗑】 震下離上","description":"周易尚氏學 - 21、【噬嗑】 震下離上"},"headers":[],"relativePath":"classics/shangshi/026.md","filePath":"classics/shangshi/026.md"}'),s={name:"classics/shangshi/026.md"};function h(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_21、【噬嗑】-震下離上" tabindex="-1">21、【噬嗑】 震下離上 <a class="header-anchor" href="#_21、【噬嗑】-震下離上" aria-label="Permalink to “21、【噬嗑】 震下離上”">​</a></h1><p>噬嗑也。嗑合也。亨通也。夫上下之不能相合者。中必有物間之。嗑而去其間。則合而通矣。國家之有刑獄。亦復如是。民有梗化者。以刑剋之。則頑梗去。而上下通矣。故曰利用獄。震為口。頤利求口實是也。為口故曰噬。雷電合居於東。故曰合而重。震為口。初至四。正反震口合。上離。正反兌口合。故曰噬嗑。自覆象失傳。及震為口之象亡。噬嗑之義。遂晦而不明。卦一陰一陽。剛柔交。故曰亨。坎為獄。折獄之道。不明則人不服。不威則眾不從。今威明並濟。故利。</p><p>彖曰。頤中有物曰噬嗑。噬嗑而亨。剛柔分。動而明。雷電合而童。柔得中而上行。雖不當位。利用獄也。</p><p>有物謂四。四在顧中。故曰有物。頤上下陽。中四交皆陰。陰順陽。故求得口食。今四陽橫互於中。陽遇陽為仇為敵。不順。嗑去此物。則合而通。故曰噬嗑而亨。卦陽爻與陰交相間。故曰剛柔分。雷電合居於東。故曰合而章。五不當位。然文明以中。斷制枉直。不失情理。故利用獄也。</p><p>象曰。雷電。噬嗑。先王以明罰敕法。</p><p>罰法皆坎象。敕（右力）正也。威之用。明則離之用也，</p><p>初九。屨校減趾。無咎。</p><p>震為趾。坎為校。初臨重陰。利往。往而遇坎。坎在震上。故曰屨校。校械也。屨貫也。言以械貫於震足之上。足不見。故曰減趾。初當位。故無咎。</p><h3 id="象日。屨校減趾。不行也。" tabindex="-1">象日。屨校減趾。不行也。 <a class="header-anchor" href="#象日。屨校減趾。不行也。" aria-label="Permalink to “象日。屨校減趾。不行也。”">​</a></h3><p>此言人初有過。其過尚微。故罰亦從輕。使有所懲。而不至積累其罪。以至於誅。所謂小懲大戒也。初本利行。行而遇險。故不行。</p><p>六二。噬膚減鼻。無咎。</p><p>震為噬。二艮體。故曰膚。曰鼻。言艮膚艮鼻。為震口所噬。隱伏於坎水之下。故曰減。二乘剛。故有是象。按減趾有類於刖刑。減鼻有類於劓刑。皆初犯罪。刑之輕者。皆冀其有所懲於後也。二得中。故可免於咎。</p><h3 id="象曰。噬膚減鼻。乘剛也。" tabindex="-1">象曰。噬膚減鼻。乘剛也。 <a class="header-anchor" href="#象曰。噬膚減鼻。乘剛也。" aria-label="Permalink to “象曰。噬膚減鼻。乘剛也。”">​</a></h3><p>乘剛不順。</p><p>六三。噬臘肉。遇毒。小吝。無咎。</p><p>說文臘乾肉也。民堅故曰臘。坎為肉。故三爻四爻五爻皆言肉。坎為毒。遇毒者。坎在前也。坎肉象。詳焦氏易詁然有應故小識破。無咎。王弼曰。噬以喻刑人。臘以喻不服。毒以喻怨生。按三不當位。以斯用刑。民必不服。豈惟不服。怨毒以生。言小民不知懲戒。仍積惡不俊也。</p><h3 id="象曰。遇毒。" tabindex="-1">象曰。遇毒。 <a class="header-anchor" href="#象曰。遇毒。" aria-label="Permalink to “象曰。遇毒。”">​</a></h3><p>位不當也。三陽位。</p><p>九四。噬乾胏。得金矢。利艱貞。吉。</p><p>胏。玉篇。肉帶骨也。離艮皆為火。坎肉居中。故曰幹胏。艮為金。坎為矢。詳焦氏易詁四艮主爻。故曰金。亦坎主爻。故曰金矢。坎陷故利艱貞。按周禮大司寇以兩造兩劑。禁民獄訟。人束矢鈞金。然後聽之。茲雲得金矢。仍寓止訟之意。夫今民人金矢。原欲止其獄訟。茲曰得金矢。是訟者不止。而益深其罪也。</p><h3 id="象曰。利艱貞吉。未光也。" tabindex="-1">象曰。利艱貞吉。未光也。 <a class="header-anchor" href="#象曰。利艱貞吉。未光也。" aria-label="Permalink to “象曰。利艱貞吉。未光也。”">​</a></h3><p>坎隱伏故曰未光。升五則光矣。</p><p>六五。噬乾肉。得黃金。貞厲。無咎。</p><p>離火故仍曰乾肉。離色黃。五履艮金上。故曰得黃金。貞卜問。失位。故貞厲。得中。故無咎。按五位雖尊。然不當位。以斯噬物。物亦不服。其堅有如噬乾肉之難。夫據尊位。能行其戮者也。乃物仍不服。不知誡懼。則其估惡不俊（左心）。頑堅難化也明矣。故曰得黃金。言其堅愈進也。得黃金非吉辭。如吉則下不日貞厲矣。</p><h3 id="象曰。貞厲無咎。得當也" tabindex="-1">象曰。貞厲無咎。得當也 <a class="header-anchor" href="#象曰。貞厲無咎。得當也" aria-label="Permalink to “象曰。貞厲無咎。得當也”">​</a></h3><p>得當者。得中也。</p><h3 id="上九。何校嚴耳。兇。" tabindex="-1">上九。何校嚴耳。兇。 <a class="header-anchor" href="#上九。何校嚴耳。兇。" aria-label="Permalink to “上九。何校嚴耳。兇。”">​</a></h3><p>坎為校為耳。上應在三。三坎體亦艮體。良為背為何。坎校在民背上。耳則遮矣。故曰嚴耳。易爻在此。而象全在應。此其一也。王弼曰處罰之極。惡積不改者也。罪非所懲。故刑及其首。及首非誡。減耳非懲。兇莫甚焉。正義曰。罪未及首。猶可戒懼歸善。罪已及首。性命將盡。非復可戒。故云及首非戒也。校既滅耳。將欲刑殺。非可懲改。故云滅耳非懲也。</p><h3 id="象曰。何校又耳。聰不明也。" tabindex="-1">象曰。何校又耳。聰不明也。 <a class="header-anchor" href="#象曰。何校又耳。聰不明也。" aria-label="Permalink to “象曰。何校又耳。聰不明也。”">​</a></h3><p>滅耳則有害於聰。故曰不明。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
